"""Main application window for Silmulator."""

from __future__ import annotations
import json
import os
from typing import Optional

from PyQt6.QtWidgets import (
    QMainWindow, QToolBar, QDockWidget, QWidget, QVBoxLayout,
    QHBoxLayout, QLabel, QPushButton, QListWidget, QListWidgetItem,
    QStatusBar, QMessageBox, QFileDialog, QSplitter, QTextEdit,
    QMenuBar, QMenu, QApplication,
)
from PyQt6.QtCore import Qt, QTimer, pyqtSlot
from PyQt6.QtGui import QAction, QFont, QColor, QIcon, QKeySequence

from silmulator.gui.canvas import CanvasScene, CanvasView, BLOCK_REGISTRY
from silmulator.gui.blocks.base_block import BaseBlock
from silmulator.gui.dialogs.device_config import DeviceConfigDialog


class BlockLibraryPanel(QWidget):
    """Side panel listing available hardware blocks that can be dragged onto the canvas."""

    def __init__(self, canvas: CanvasScene) -> None:
        super().__init__()
        self.canvas = canvas
        self._setup_ui()

    def _setup_ui(self) -> None:
        layout = QVBoxLayout(self)
        layout.setContentsMargins(4, 4, 4, 4)

        title = QLabel("Hardware Blocks")
        title.setFont(QFont("Consolas", 10, QFont.Weight.Bold))
        layout.addWidget(title)

        self._list = QListWidget()
        self._list.setFont(QFont("Consolas", 9))

        descriptions = {
            "Oscilloscope": "Tektronix MSO54-compatible\n4-channel, 1GHz, SCPI",
            "Power Supply": "Keysight E36312A-compatible\n3-channel DC PSU",
            "Function Generator": "Keysight 33522B-compatible\n2-ch, 30MHz AWG",
            "Multimeter": "Keysight 34401A-compatible\n6.5 digit DMM",
            "MSP430": "TI MSP430FR5994\nGPIO, ADC, UART, SPI, I2C",
            "Code Input": "Code Analyzer\nC/C++/Python SCPI extractor",
        }

        for name, desc in descriptions.items():
            item = QListWidgetItem(f"{name}")
            item.setToolTip(desc)
            item.setData(Qt.ItemDataRole.UserRole, name)
            self._list.addItem(item)

        self._list.itemDoubleClicked.connect(self._add_block)
        layout.addWidget(self._list)

        add_btn = QPushButton("Add Selected Block")
        add_btn.clicked.connect(lambda: self._add_block(self._list.currentItem()))
        layout.addWidget(add_btn)

        hint = QLabel("Double-click or drag to add\nto canvas")
        hint.setStyleSheet("color: #888; font-size: 8pt;")
        layout.addWidget(hint)

    def _add_block(self, item: Optional[QListWidgetItem]) -> None:
        if item is None:
            return
        device_type = item.data(Qt.ItemDataRole.UserRole)
        # No explicit position: the canvas auto-places the block at the
        # first free spot so blocks (and their ports) never overlap.
        self.canvas.add_block(device_type)


class ConsolePanel(QWidget):
    """SCPI command console panel."""

    def __init__(self, canvas: CanvasScene) -> None:
        super().__init__()
        self.canvas = canvas
        self._setup_ui()

    def _setup_ui(self) -> None:
        layout = QVBoxLayout(self)
        layout.setContentsMargins(4, 4, 4, 4)

        title = QLabel("SCPI Console")
        title.setFont(QFont("Consolas", 10, QFont.Weight.Bold))
        layout.addWidget(title)

        # Block selector
        block_bar = QHBoxLayout()
        block_bar.addWidget(QLabel("Target:"))
        self._block_combo_label = QLabel("(select a block on canvas)")
        block_bar.addWidget(self._block_combo_label)
        block_bar.addStretch()
        layout.addLayout(block_bar)

        # Output
        self._output = QTextEdit()
        self._output.setReadOnly(True)
        self._output.setFont(QFont("Consolas", 9))
        self._output.setStyleSheet("background: #1a1a2e; color: #00ff88;")
        layout.addWidget(self._output)

        # Input
        input_bar = QHBoxLayout()
        self._cmd_input = QTextEdit()
        self._cmd_input.setMaximumHeight(60)
        self._cmd_input.setFont(QFont("Consolas", 10))
        self._cmd_input.setPlaceholderText("SCPI command (Ctrl+Enter to send)")
        input_bar.addWidget(self._cmd_input)
        send_btn = QPushButton("Send")
        send_btn.setFixedWidth(60)
        send_btn.clicked.connect(self._send)
        input_bar.addWidget(send_btn)
        layout.addLayout(input_bar)

    def _send(self) -> None:
        cmd = self._cmd_input.toPlainText().strip()
        if not cmd:
            return
        # Send to all selected blocks
        selected = [
            item for item in self.canvas.selectedItems()
            if isinstance(item, BaseBlock)
        ]
        if not selected:
            self._output.append("<i>No block selected on canvas</i>")
            return
        for block in selected:
            response = block.send_command(cmd)
            self._output.append(f"<b>[{block.device_type}]</b> >> {cmd}")
            if response:
                self._output.append(f"<b>&lt;&lt;</b> {response}")
        self._cmd_input.clear()

    def log(self, message: str) -> None:
        self._output.append(message)


class MainWindow(QMainWindow):
    """Silmulator main application window."""

    def __init__(self) -> None:
        super().__init__()
        self.setWindowTitle("Silmulator — SIL/HIL/CIL Hardware Simulator")
        self.resize(1400, 900)
        self._current_file: Optional[str] = None
        self._setup_scene()
        self._setup_ui()
        self._setup_menus()
        self._setup_toolbar()
        self._setup_statusbar()
        self._apply_dark_theme()
        self._statusbar.showMessage("Ready — Double-click blocks in the library to add them to the canvas")

    # ------------------------------------------------------------------
    # Setup
    # ------------------------------------------------------------------

    def _setup_scene(self) -> None:
        self.canvas = CanvasScene()
        self.canvas_view = CanvasView(self.canvas)
        self.canvas.block_added.connect(self._on_block_added)
        self.canvas.block_removed.connect(self._on_block_removed)
        self.canvas.wire_added.connect(self._on_wire_added)

    def _setup_ui(self) -> None:
        # Central widget
        self.setCentralWidget(self.canvas_view)

        # Left dock: block library
        lib_dock = QDockWidget("Library", self)
        lib_dock.setAllowedAreas(Qt.DockWidgetArea.LeftDockWidgetArea | Qt.DockWidgetArea.RightDockWidgetArea)
        self._library_panel = BlockLibraryPanel(self.canvas)
        self._library_panel.setMinimumWidth(180)
        lib_dock.setWidget(self._library_panel)
        self.addDockWidget(Qt.DockWidgetArea.LeftDockWidgetArea, lib_dock)

        # Bottom dock: console
        console_dock = QDockWidget("SCPI Console", self)
        console_dock.setAllowedAreas(Qt.DockWidgetArea.BottomDockWidgetArea | Qt.DockWidgetArea.TopDockWidgetArea)
        self._console = ConsolePanel(self.canvas)
        self._console.setMinimumHeight(150)
        console_dock.setWidget(self._console)
        self.addDockWidget(Qt.DockWidgetArea.BottomDockWidgetArea, console_dock)

    def _setup_menus(self) -> None:
        mb = self.menuBar()

        # File menu
        file_menu = mb.addMenu("&File")
        file_menu.addAction(self._make_action("&New", "Ctrl+N", self._new_canvas))
        file_menu.addAction(self._make_action("&Open...", "Ctrl+O", self._open_layout))
        file_menu.addAction(self._make_action("&Save", "Ctrl+S", self._save_layout))
        file_menu.addAction(self._make_action("Save &As...", "Ctrl+Shift+S", self._save_layout_as))
        file_menu.addSeparator()
        file_menu.addAction(self._make_action("&Quit", "Ctrl+Q", self.close))

        # Edit menu
        edit_menu = mb.addMenu("&Edit")
        edit_menu.addAction(self._make_action("Select &All", "Ctrl+A", self.canvas.selectAll))
        edit_menu.addAction(self._make_action("&Delete Selected", "Del",
                                               self._delete_selected))

        # Add menu
        add_menu = mb.addMenu("&Add")
        for name in BLOCK_REGISTRY:
            add_menu.addAction(self._make_action(name, None,
                               lambda checked, n=name: self.canvas.add_block(n)))

        # View menu
        view_menu = mb.addMenu("&View")
        view_menu.addAction(self._make_action("Fit &All", "Ctrl+Shift+F", self.canvas_view.fit_all))
        view_menu.addAction(self._make_action("Reset &Zoom", "Ctrl+0",
                                               self.canvas_view.resetTransform))

        # Simulate menu
        sim_menu = mb.addMenu("&Simulate")
        sim_menu.addAction(self._make_action("&Reset All Devices", "Ctrl+R", self._reset_all))
        sim_menu.addAction(self._make_action("Send Broadcast Command...", None, self._broadcast))

        # Help menu
        help_menu = mb.addMenu("&Help")
        help_menu.addAction(self._make_action("&About", None, self._about))

    def _make_action(self, text: str, shortcut: Optional[str], slot) -> QAction:
        action = QAction(text, self)
        if shortcut:
            action.setShortcut(QKeySequence(shortcut))
        action.triggered.connect(slot)
        return action

    def _setup_toolbar(self) -> None:
        tb = self.addToolBar("Main")
        tb.setMovable(False)

        for name in BLOCK_REGISTRY:
            btn = QPushButton(name)
            btn.setFixedHeight(30)
            btn.clicked.connect(lambda checked, n=name: self.canvas.add_block(n))
            tb.addWidget(btn)

        tb.addSeparator()
        reset_btn = QPushButton("Reset All")
        reset_btn.clicked.connect(self._reset_all)
        tb.addWidget(reset_btn)

        fit_btn = QPushButton("Fit View")
        fit_btn.clicked.connect(self.canvas_view.fit_all)
        tb.addWidget(fit_btn)

    def _setup_statusbar(self) -> None:
        self._statusbar = QStatusBar()
        self.setStatusBar(self._statusbar)
        self._block_count_label = QLabel("Blocks: 0  Wires: 0")
        self._statusbar.addPermanentWidget(self._block_count_label)

    # ------------------------------------------------------------------
    # Actions
    # ------------------------------------------------------------------

    def _new_canvas(self) -> None:
        if self.canvas.blocks:
            reply = QMessageBox.question(
                self, "New Canvas",
                "Clear the current canvas?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
            )
            if reply != QMessageBox.StandardButton.Yes:
                return
        self.canvas.clear()
        self._current_file = None
        self.setWindowTitle("Silmulator — Untitled")
        self._update_status()

    def _open_layout(self) -> None:
        path, _ = QFileDialog.getOpenFileName(
            self, "Open Layout", "",
            "Silmulator Layout (*.sil);;JSON (*.json);;All Files (*)"
        )
        if path:
            try:
                with open(path) as f:
                    data = json.load(f)
                self.canvas.from_dict(data)
                self._current_file = path
                self.setWindowTitle(f"Silmulator — {os.path.basename(path)}")
                self._update_status()
                self._console.log(f"Loaded layout: {path}")
            except Exception as e:
                QMessageBox.critical(self, "Load Error", str(e))

    def _save_layout(self) -> None:
        if self._current_file:
            self._do_save(self._current_file)
        else:
            self._save_layout_as()

    def _save_layout_as(self) -> None:
        path, _ = QFileDialog.getSaveFileName(
            self, "Save Layout", "",
            "Silmulator Layout (*.sil);;JSON (*.json);;All Files (*)"
        )
        if path:
            if not path.endswith(('.sil', '.json')):
                path += '.sil'
            self._do_save(path)

    def _do_save(self, path: str) -> None:
        try:
            data = self.canvas.to_dict()
            with open(path, 'w') as f:
                json.dump(data, f, indent=2)
            self._current_file = path
            self.setWindowTitle(f"Silmulator — {os.path.basename(path)}")
            self._statusbar.showMessage(f"Saved: {path}")
        except Exception as e:
            QMessageBox.critical(self, "Save Error", str(e))

    def _delete_selected(self) -> None:
        for item in self.canvas.selectedItems():
            if isinstance(item, BaseBlock):
                self.canvas.remove_block(item)

    def _reset_all(self) -> None:
        for block in self.canvas.blocks:
            block.device.reset()
        self._console.log("All devices reset")
        self.canvas.update()

    def _broadcast(self) -> None:
        from PyQt6.QtWidgets import QInputDialog
        cmd, ok = QInputDialog.getText(self, "Broadcast SCPI Command",
                                        "Send to all blocks:")
        if ok and cmd:
            for block in self.canvas.blocks:
                resp = block.send_command(cmd)
                self._console.log(f"[{block.device_type}] >> {cmd}")
                if resp:
                    self._console.log(f"[{block.device_type}] << {resp}")

    def _about(self) -> None:
        QMessageBox.about(
            self, "About Silmulator",
            "<h3>Silmulator v1.0.0</h3>"
            "<p>SIL/HIL/CIL Hardware Simulator</p>"
            "<p>Simulated instruments:</p>"
            "<ul>"
            "<li>Oscilloscope (Tektronix MSO54-compatible)</li>"
            "<li>Power Supply (Keysight E36312A-compatible)</li>"
            "<li>Function Generator (Keysight 33522B-compatible)</li>"
            "<li>Multimeter (Keysight 34401A-compatible)</li>"
            "<li>MSP430 Microcontroller (TI MSP430FR5994)</li>"
            "</ul>"
            "<p>Each instrument implements the full SCPI command set.</p>"
        )

    # ------------------------------------------------------------------
    # Slots
    # ------------------------------------------------------------------

    @pyqtSlot(str, str)
    def _on_block_added(self, block_id: str, device_type: str) -> None:
        self._console.log(f"Added {device_type} [{block_id}]")
        self._update_status()

    @pyqtSlot(str)
    def _on_block_removed(self, block_id: str) -> None:
        self._console.log(f"Removed block [{block_id}]")
        self._update_status()

    @pyqtSlot(str, str, str, str)
    def _on_wire_added(self, src_block: str, src_port: str, dst_block: str, dst_port: str) -> None:
        self._console.log(f"Connected [{src_block}].{src_port} → [{dst_block}].{dst_port}")
        self._update_status()

    def _update_status(self) -> None:
        n_blocks = len(self.canvas.blocks)
        n_wires = len(self.canvas._wires)
        self._block_count_label.setText(f"Blocks: {n_blocks}  Wires: {n_wires}")

    # ------------------------------------------------------------------
    # Theme
    # ------------------------------------------------------------------

    def _apply_dark_theme(self) -> None:
        self.setStyleSheet("""
            QMainWindow, QWidget {
                background-color: #1e2330;
                color: #d0d8f0;
            }
            QToolBar {
                background-color: #252b3b;
                border-bottom: 1px solid #3a4060;
                spacing: 4px;
                padding: 2px;
            }
            QPushButton {
                background-color: #2e3a5a;
                color: #c8d8ff;
                border: 1px solid #4a5a80;
                border-radius: 4px;
                padding: 4px 8px;
                font-family: Consolas;
            }
            QPushButton:hover {
                background-color: #3a4a70;
                border-color: #6a7aaa;
            }
            QPushButton:pressed {
                background-color: #1a2a4a;
            }
            QDockWidget {
                color: #c0c8e0;
                font-family: Consolas;
            }
            QDockWidget::title {
                background-color: #252b3b;
                padding: 4px;
            }
            QListWidget {
                background-color: #1a1f2e;
                border: 1px solid #3a4060;
                color: #c0d0f0;
            }
            QListWidget::item:selected {
                background-color: #2e4070;
            }
            QTextEdit {
                background-color: #141a28;
                border: 1px solid #3a4060;
                color: #c0d0f0;
                font-family: Consolas;
            }
            QMenuBar {
                background-color: #1a1f2e;
                color: #c0d0f0;
            }
            QMenuBar::item:selected {
                background-color: #2e4070;
            }
            QMenu {
                background-color: #252b3b;
                color: #c0d0f0;
                border: 1px solid #3a4060;
            }
            QMenu::item:selected {
                background-color: #2e4070;
            }
            QStatusBar {
                background-color: #1a1f2e;
                color: #808890;
            }
            QLabel {
                color: #c0d0f0;
            }
        """)

"""Drag-and-drop canvas for hardware blocks."""

from __future__ import annotations
from typing import Optional, Dict, List, Tuple
import uuid
import json

from PyQt6.QtWidgets import (
    QGraphicsScene, QGraphicsView, QGraphicsLineItem,
    QGraphicsItem, QSizePolicy, QMenu, QApplication,
)
from PyQt6.QtCore import Qt, QPointF, QRectF, QLineF, QSizeF, pyqtSignal, QObject
from PyQt6.QtGui import (
    QPainter, QColor, QPen, QBrush, QWheelEvent,
    QMouseEvent, QKeyEvent,
)

from silmulator.gui.blocks.base_block import BaseBlock, ConnectionPort
from silmulator.gui.blocks.oscilloscope_block import OscilloscopeBlock
from silmulator.gui.blocks.power_supply_block import PowerSupplyBlock
from silmulator.gui.blocks.function_generator_block import FunctionGeneratorBlock
from silmulator.gui.blocks.multimeter_block import MultimeterBlock
from silmulator.gui.blocks.msp430_block import MSP430Block
from silmulator.gui.blocks.code_input_block import CodeInputBlock
from silmulator.gui.blocks.custom_block import register_custom_blocks


BLOCK_REGISTRY = {
    "Oscilloscope": OscilloscopeBlock,
    "Power Supply": PowerSupplyBlock,
    "Function Generator": FunctionGeneratorBlock,
    "Multimeter": MultimeterBlock,
    "MSP430": MSP430Block,
    "Code Input": CodeInputBlock,
}

# Auto-discover and register user-authored JSON spec blocks. Failures here
# are non-fatal — built-in blocks are still available even if a spec is
# malformed.
try:
    register_custom_blocks(BLOCK_REGISTRY)
except Exception:
    pass


class WireItem(QGraphicsLineItem):
    """A connection wire between two ports."""

    def __init__(self, src: ConnectionPort, dst: ConnectionPort) -> None:
        super().__init__()
        self.src_port = src
        self.dst_port = dst
        self.wire_id = str(uuid.uuid4())[:8]
        pen = QPen(QColor(255, 200, 50), 2, Qt.PenStyle.SolidLine,
                   Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin)
        self.setPen(pen)
        self.setZValue(-1)
        self.update_position()

    def update_position(self) -> None:
        src_pos = self.src_port.scenePos()
        dst_pos = self.dst_port.scenePos()
        self.setLine(QLineF(src_pos, dst_pos))

    def paint(self, painter: QPainter, option, widget=None) -> None:
        # Draw with anti-aliasing
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        super().paint(painter, option, widget)


class CanvasScene(QGraphicsScene):
    """Scene that holds hardware blocks and wires."""

    block_added = pyqtSignal(str, str)    # block_id, device_type
    block_removed = pyqtSignal(str)       # block_id
    wire_added = pyqtSignal(str, str, str, str)   # src_block, src_port, dst_block, dst_port
    wire_removed = pyqtSignal(str)        # wire_id
    command_executed = pyqtSignal(str, str, str)  # block_id, cmd, response

    GRID_SIZE = 20
    BACKGROUND_COLOR = QColor(28, 32, 40)
    GRID_COLOR = QColor(45, 52, 65)
    # Clearance around each block so edge ports (port radius ~6px) and
    # wires between neighbours stay visible.
    PLACEMENT_MARGIN = 40

    def __init__(self) -> None:
        super().__init__()
        self._blocks: Dict[str, BaseBlock] = {}
        self._wires: Dict[str, WireItem] = {}
        self._connecting: Optional[ConnectionPort] = None
        self._temp_wire: Optional[QGraphicsLineItem] = None
        self.setBackgroundBrush(QBrush(self.BACKGROUND_COLOR))
        self.setSceneRect(-2000, -2000, 4000, 4000)

    # ------------------------------------------------------------------
    # Block management
    # ------------------------------------------------------------------

    def add_block(self, device_type: str, pos: Optional[QPointF] = None) -> Optional[BaseBlock]:
        """Create a block of ``device_type`` and add it to the scene.

        When ``pos`` is None the block is auto-placed at the first free
        spot so newly added blocks never stack on top of each other.
        """
        cls = BLOCK_REGISTRY.get(device_type)
        if cls is None:
            return None
        block = cls()
        if pos is None:
            pos = self.find_free_position(cls)
        block.setPos(self._snap_to_grid(pos))
        self.addItem(block)
        self._blocks[block.block_id] = block
        self.block_added.emit(block.block_id, device_type)
        return block

    def find_free_position(self, block_cls: type) -> QPointF:
        """Return the first grid-aligned position where a ``block_cls``-sized
        block does not overlap any existing block (including a margin for
        edge-mounted connection ports).

        Falls back to the top-left corner if the scene is fully packed —
        callers must tolerate overlap in that extreme case.
        """
        occupied = [
            QRectF(b.x(), b.y(), b.BLOCK_WIDTH, b.BLOCK_HEIGHT)
            .adjusted(-self.PLACEMENT_MARGIN, -self.PLACEMENT_MARGIN,
                      self.PLACEMENT_MARGIN, self.PLACEMENT_MARGIN)
            for b in self._blocks.values()
        ]
        r = self.sceneRect()
        start_x = r.left() + self.PLACEMENT_MARGIN
        start_y = r.top() + self.PLACEMENT_MARGIN
        w = block_cls.BLOCK_WIDTH + self.PLACEMENT_MARGIN
        h = block_cls.BLOCK_HEIGHT + self.PLACEMENT_MARGIN
        y = start_y
        while y + h <= r.bottom():
            x = start_x
            while x + w <= r.right():
                candidate = QRectF(x, y, w, h)
                if not any(candidate.intersects(occ) for occ in occupied):
                    return QPointF(x, y)
                x += self.GRID_SIZE
            y += self.GRID_SIZE
        import warnings
        warnings.warn(
            "find_free_position: scene fully packed, new block will overlap existing blocks",
            stacklevel=2,
        )
        return QPointF(start_x, start_y)

    def remove_block(self, block: BaseBlock) -> None:
        # Remove connected wires first
        wires_to_remove = [
            w for w in self._wires.values()
            if (w.src_port.parent_block is block or
                w.dst_port.parent_block is block)
        ]
        for wire in wires_to_remove:
            self._remove_wire(wire)
        self._blocks.pop(block.block_id, None)
        self.removeItem(block)
        self.block_removed.emit(block.block_id)

    def get_block(self, block_id: str) -> Optional[BaseBlock]:
        return self._blocks.get(block_id)

    @property
    def blocks(self) -> List[BaseBlock]:
        return list(self._blocks.values())

    def selectAll(self) -> None:
        for item in self.items():
            if item.flags() & item.GraphicsItemFlag.ItemIsSelectable:
                item.setSelected(True)

    def clear(self) -> None:
        """Remove every item and reset all bookkeeping.

        QGraphicsScene.clear() deletes the underlying C++ items, so the
        block/wire registries must be reset too or they would hold
        dangling references (crashing the next save / reset-all).
        """
        super().clear()
        self._blocks = {}
        self._wires = {}
        self._connecting = None
        self._temp_wire = None

    # ------------------------------------------------------------------
    # Wire management
    # ------------------------------------------------------------------

    def connect_ports(self, src: ConnectionPort, dst: ConnectionPort) -> Optional[WireItem]:
        if src.parent_block is dst.parent_block:
            return None  # Don't connect a block to itself
        if src.connected_to or dst.connected_to:
            return None  # Already connected

        wire = WireItem(src, dst)
        self.addItem(wire)
        self._wires[wire.wire_id] = wire
        src.connect_to(dst)
        self.wire_added.emit(
            src.parent_block.block_id, src.port_id,
            dst.parent_block.block_id, dst.port_id
        )
        return wire

    def disconnect_ports(self, wire: WireItem) -> None:
        self._remove_wire(wire)

    def _remove_wire(self, wire: WireItem) -> None:
        wire.src_port.disconnect()
        wire.dst_port.disconnect()
        self._wires.pop(wire.wire_id, None)
        self.removeItem(wire)
        self.wire_removed.emit(wire.wire_id)

    # ------------------------------------------------------------------
    # Wire drawing interaction
    # ------------------------------------------------------------------

    def mousePressEvent(self, event) -> None:
        if event.button() == Qt.MouseButton.LeftButton:
            port = self._port_at(event.scenePos())
            if port is not None and port.connected_to is None:
                self._start_wire(port, event.scenePos())
                # Accept the event: an unaccepted press makes the
                # QGraphicsView (RubberBandDrag mode) start a rubber-band
                # selection that draws over and fights the wire drag.
                event.accept()
                return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event) -> None:
        if self._connecting and self._temp_wire:
            self._temp_wire.setLine(
                QLineF(self._connecting.scenePos(), event.scenePos())
            )
            # Update all committed wires while dragging so any block that
            # gets nudged during the gesture keeps its wire taut.
            for wire in self._wires.values():
                wire.update_position()
            # Don't let the scene start a rubber-band / item drag while wiring.
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event) -> None:
        if self._connecting and event.button() == Qt.MouseButton.LeftButton:
            target = self._port_at(event.scenePos())
            if target is not None and target is not self._connecting:
                self.connect_ports(self._connecting, target)
            self._cancel_wire()
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def _port_at(self, pos: QPointF) -> Optional[ConnectionPort]:
        """Return the topmost ConnectionPort at the given scene pos, ignoring
        the in-progress temp wire and any other non-port items above it."""
        for item in self.items(pos):
            if item is self._temp_wire:
                continue
            if isinstance(item, ConnectionPort):
                return item
        return None

    def _start_wire(self, port: ConnectionPort, pos: QPointF) -> None:
        self._connecting = port
        pen = QPen(QColor(255, 200, 50), 2, Qt.PenStyle.DashLine)
        self._temp_wire = self.addLine(QLineF(pos, pos), pen)
        self._temp_wire.setZValue(100)
        # Keep the rubber-line out of hit testing so itemAt-style lookups
        # at the cursor still resolve to the destination port underneath.
        self._temp_wire.setAcceptedMouseButtons(Qt.MouseButton.NoButton)
        self._temp_wire.setFlag(
            QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, False
        )

    def _cancel_wire(self) -> None:
        if self._temp_wire:
            self.removeItem(self._temp_wire)
            self._temp_wire = None
        self._connecting = None

    # ------------------------------------------------------------------
    # Grid snap
    # ------------------------------------------------------------------

    def _snap_to_grid(self, pos: QPointF) -> QPointF:
        g = self.GRID_SIZE
        return QPointF(
            round(pos.x() / g) * g,
            round(pos.y() / g) * g,
        )

    # ------------------------------------------------------------------
    # Grid drawing
    # ------------------------------------------------------------------

    def drawBackground(self, painter: QPainter, rect: QRectF) -> None:
        super().drawBackground(painter, rect)
        painter.setPen(QPen(self.GRID_COLOR, 0.5))
        g = self.GRID_SIZE
        left = int(rect.left() - (rect.left() % g))
        top = int(rect.top() - (rect.top() % g))
        x = left
        while x < rect.right():
            painter.drawLine(int(x), int(rect.top()), int(x), int(rect.bottom()))
            x += g
        y = top
        while y < rect.bottom():
            painter.drawLine(int(rect.left()), int(y), int(rect.right()), int(y))
            y += g

    # ------------------------------------------------------------------
    # Layout persistence
    # ------------------------------------------------------------------

    def to_dict(self) -> dict:
        blocks = []
        for block in self._blocks.values():
            blocks.append({
                "id": block.block_id,
                "type": block.device_type,
                "name": block.name,
                "x": block.x(),
                "y": block.y(),
            })
        wires = []
        for wire in self._wires.values():
            wires.append({
                "id": wire.wire_id,
                "src_block": wire.src_port.parent_block.block_id,
                "src_port": wire.src_port.port_id,
                "dst_block": wire.dst_port.parent_block.block_id,
                "dst_port": wire.dst_port.port_id,
            })
        return {"blocks": blocks, "wires": wires}

    def from_dict(self, data: dict) -> None:
        self.clear()
        port_map: Dict[Tuple[str, str], ConnectionPort] = {}
        for bdata in data.get("blocks", []):
            block = self.add_block(bdata["type"], QPointF(bdata["x"], bdata["y"]))
            if block:
                block.name = bdata.get("name", block.name)
                for port in block.ports:
                    port_map[(bdata["id"], port.port_id)] = port
        for wdata in data.get("wires", []):
            src = port_map.get((wdata["src_block"], wdata["src_port"]))
            dst = port_map.get((wdata["dst_block"], wdata["dst_port"]))
            if src and dst:
                self.connect_ports(src, dst)


class CanvasView(QGraphicsView):
    """Zoomable, pannable view for the canvas scene."""

    def __init__(self, scene: CanvasScene) -> None:
        super().__init__(scene)
        self.setRenderHint(QPainter.RenderHint.Antialiasing)
        self.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        self.setDragMode(QGraphicsView.DragMode.RubberBandDrag)
        self.setViewportUpdateMode(QGraphicsView.ViewportUpdateMode.BoundingRectViewportUpdate)
        self.setTransformationAnchor(QGraphicsView.ViewportAnchor.AnchorUnderMouse)
        self.setResizeAnchor(QGraphicsView.ViewportAnchor.AnchorViewCenter)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self._panning = False
        self._pan_start = QPointF()

    def wheelEvent(self, event: QWheelEvent) -> None:
        factor = 1.15 if event.angleDelta().y() > 0 else 1 / 1.15
        current = self.transform().m11()
        if (factor < 1 and current > 0.1) or (factor > 1 and current < 8.0):
            self.scale(factor, factor)

    def mousePressEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.MiddleButton:
            self._panning = True
            self._pan_start = event.position()
            self.setDragMode(QGraphicsView.DragMode.NoDrag)
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
        else:
            super().mousePressEvent(event)

    def mouseMoveEvent(self, event: QMouseEvent) -> None:
        if self._panning:
            delta = event.position() - self._pan_start
            self._pan_start = event.position()
            self.horizontalScrollBar().setValue(
                int(self.horizontalScrollBar().value() - delta.x())
            )
            self.verticalScrollBar().setValue(
                int(self.verticalScrollBar().value() - delta.y())
            )
        else:
            super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.MiddleButton:
            self._panning = False
            self.setDragMode(QGraphicsView.DragMode.RubberBandDrag)
            self.setCursor(Qt.CursorShape.ArrowCursor)
        else:
            super().mouseReleaseEvent(event)

    def keyPressEvent(self, event: QKeyEvent) -> None:
        if event.key() == Qt.Key.Key_Delete:
            for item in self.scene().selectedItems():
                if isinstance(item, BaseBlock):
                    self.scene().remove_block(item)
        elif event.key() == Qt.Key.Key_Escape:
            if isinstance(self.scene(), CanvasScene):
                self.scene()._cancel_wire()
        elif event.modifiers() & Qt.KeyboardModifier.ControlModifier:
            if event.key() == Qt.Key.Key_0:
                self.resetTransform()
            elif event.key() == Qt.Key.Key_A:
                self.scene().selectAll()
        else:
            super().keyPressEvent(event)

    def fit_all(self) -> None:
        if self.scene().items():
            self.fitInView(self.scene().itemsBoundingRect().adjusted(-20, -20, 20, 20),
                           Qt.AspectRatioMode.KeepAspectRatio)

